const $=s=>document.querySelector(s), key='statistiklabor-v1';
let state={notes:{},checks:{},done:{}};try{const s=JSON.parse(localStorage.getItem(key));if(s&&s.notes&&s.checks&&s.done)state=s}catch{}
state.quiz=state.quiz||{};state.activity=state.activity||{};state.calc=state.calc||{};
const answerRules={beschreibung:[40,220],abstand:[60,350],kritik:[60,350],achse:[35,200],mittelwert:[40,220],vergleich:[40,220],energie:[45,250],urteil:[100,600],forschungsplan:[60,350],revision:[30,160]};
function assessAnswer(id,value){
 const [minWords,minChars]=answerRules[id];
 const text=String(value||'').normalize('NFKC').trim();
 const words=(text.toLocaleLowerCase('de-DE').match(/\p{L}{2,}(?:[-’']\p{L}{2,})*/gu)||[]);
 const unique=new Set(words).size;
 const counts={};for(const word of words)counts[word]=(counts[word]||0)+1;
 const repeated=words.length>0&&(Math.max(...Object.values(counts))/words.length>.22||unique<Math.min(20,minWords/2)||unique/words.length<.3);
 const malformed=/(.)\1{5,}/u.test(text)||words.filter(w=>!/[aeiouyäöü]/i.test(w)||w.length>35).length>words.length*.25;
 const letters=(text.match(/\p{L}/gu)||[]).length;
 const ready=words.length>=minWords&&text.length>=minChars&&!repeated&&!malformed&&letters/text.length>.55;
 return {ready,words:words.length,minWords,minChars,message:ready?'Ausreichender Bearbeitungsumfang erreicht. Prüfe die fachliche Qualität am Kriterienraster.':`Noch nicht ausreichend: mindestens ${minWords} Wörter und ${minChars} Zeichen in eigenen, zusammenhängenden Sätzen. Aktuell ${words.length} Wörter und ${text.length} Zeichen.${repeated||malformed?' Vermeide Wiederholungen und Zeichenfolgen.':''}`};
}
const stationRules={
 beschreiben:[['text','beschreibung','Statistik-Steckbrief'],['quiz','basis','Verständnisfrage richtig beantworten']],
 auswerten:[['text','abstand','Begründeter Vergleich'],['calc','difference','Abstand richtig berechnen'],['quiz','freiheit','Aussage zur Freiheit richtig prüfen']],
 beurteilen:[['text','kritik','Kritische Argumentation'],['quiz','quelle','Quellenfrage richtig beantworten']],
 labor:[['text','achse','Achsenwahl begründen'],['text','mittelwert','Kennzahlen vergleichen'],['text','vergleich','Städtevergleich beurteilen'],['activity','axis','Achsenregler verändern'],['activity','outlier','Einkommensregler verändern'],['activity','cities','Relative Unfallzahlen aufrufen']],
 transfer:[['text','energie','Energieschlagzeilen prüfen'],['text','urteil','Gesamturteil verfassen'],['text','forschungsplan','Untersuchung planen'],['text','revision','Überarbeitung erklären'],...Array.from({length:6},(_,i)=>['check','r'+i,'Kriterium '+(i+1)+' selbst prüfen'])]
};
function requirementMet([type,id]){if(type==='text')return assessAnswer(id,state.notes[id]).ready;if(type==='quiz')return state.quiz[id]?.passed===true;if(type==='calc')return state.calc.passed===true;if(type==='check')return state.checks[id]===true;return state.activity[id]===true}
function updateCompletion(){state.done=Object.fromEntries(Object.entries(stationRules).map(([id,rules])=>[id,rules.every(requirementMet)]))}
function save(){updateCompletion();try{localStorage.setItem(key,JSON.stringify(state))}catch{$('#storage').textContent='Speichern nicht verfügbar. Lade deinen Arbeitsstand herunter.'}progress()}
const routes=[['start','Überblick'],['beschreiben','Beschreiben'],['auswerten','Auswerten'],['beurteilen','Beurteilen'],['labor','Experimentieren'],['transfer','Transfer & Urteil'],['quellen','Quellen & Begriffe']];
const data=[['Absicherung gegen Arbeitslosigkeit, Krankheit usw.',76,59],['Faire Arbeitsbedingungen und Löhne aushandeln',74,24],['Möglichst viele sichere Arbeitsplätze',69,20],['Gewerkschaften für Arbeitnehmerrechte',61,46],['Soziale Verantwortung von Unternehmen',60,13],['Chancengerechtigkeit',59,12],['Staatliche Hilfe bei unverschuldeter Not',52,28],['Gerechte Verteilung von Einkommen und Vermögen',52,4],['Fairer Wettbewerb zwischen Unternehmen',51,14],['Zusammenhalt und Solidarität',48,8],['Verantwortungsbewusstsein',47,17],['Mitbestimmung in Unternehmen',45,16],['Allgemeiner Wohlstand',44,23],['Wirtschaftswachstum',41,37],['Unternehmerische Freiheit',36,39],['Eigeninitiative',33,20],['Begrenzter Einfluss des Staates',32,19]];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function note(id,label,hint='Belege deine Aussage mit Daten und benenne eine Grenze.'){return `<label for="${id}"><strong>${label}</strong></label><small>${hint}</small><textarea id="${id}" data-note="${id}" aria-describedby="${id}-requirements ${id}-status">${esc(state.notes[id])}</textarea><small id="${id}-requirements">Mindestens ${answerRules[id][0]} Wörter und ${answerRules[id][1]} Zeichen. Begründe in eigenen Sätzen; reine Wiederholungen zählen nicht.</small><p class="answer-status" id="${id}-status" role="status"></p>`}
function details(title,body){return `<details><summary>${title}</summary>${body}</details>`}
function quiz(id,q,options,correct,explain){return `<form class="quiz" data-id="${id}" data-correct="${correct}"><fieldset><legend>${q}</legend>${options.map((o,i)=>`<label class="option"><input type="radio" name="${id}" value="${i}" required>${o}</label>`).join('')}</fieldset><button>Antwort prüfen</button><div class="feedback" role="status" data-explain="${esc(explain)}"></div></form>`}
function task(id,title,body,model){return `<section class="panel"><span class="tag">DENKAUFTRAG</span><h2>${title}</h2><p>${body}</p>${note(id,'Deine begründete Antwort')}${details('Denkhilfe',`<p>Trenne Beobachtung, Deutung und Urteil. Nenne zwei konkrete Zahlen, prüfe einen möglichen Einwand und schränke deine Schlussfolgerung sinnvoll ein.</p>`)}${details('Vergleichslösung · erst nach dem eigenen Versuch',`<p>${model}</p><p><strong>Überarbeite anschließend deine Antwort:</strong> Welches Argument fehlt? Welche Behauptung geht über die Daten hinaus?</p>`)}</section>`}
function finish(id,next){return `<div class="next">${stationRules[id]?`<div data-completion="${id}" role="status"></div>`:'<p>Die fünf Aufgabenstationen werden automatisch abgeschlossen, sobald alle Anforderungen erfüllt sind.</p>'}${next?`<a class="primary" href="#${next}">Weiter: ${routes.find(r=>r[0]===next)[1]} →</a>`:''}</div>`}
function heading(n,title,lead){return `<p class="eyebrow">${n} · STATISTIKLABOR</p><h1>${title}</h1><p class="lead">${lead}</p>`}
function socialChart(){return `<section class="panel"><span class="tag">DATENAKTE 01 · UMFRAGE 2021</span><h2>Was macht eine Soziale Marktwirtschaft aus?</h2><p>Anspruch und wahrgenommene Wirklichkeit in Deutschland. Angaben in Prozent der Bevölkerung ab 16 Jahren.</p><div class="legend"><span>Gehört dazu</span><span>In Deutschland ausreichend erfüllt</span></div><div class="toolbar"><label for="sort">Sortieren</label><select id="sort"><option value="original">Nach Zustimmung</option><option value="gap">Nach Abstand</option></select><label class="check"><input id="all" type="checkbox">Alle 17 Merkmale zeigen</label></div><div id="social-chart"></div><div class="axis"><span>0 %</span><span>50 %</span><span>100 %</span></div><small>Quelle: bereitgestellte Buchabbildung nach Allensbacher Archiv, IfD-Umfrage 12031, 2021. Beschriftungen gekürzt; Zahlen unverändert. Mehrfachnennungen sind möglich; die Kategorien ergeben keine 100-%-Aufteilung.</small>${details('Datentabelle & Quellenprüfung',`<div class="tablewrap"><table><caption>Alle 17 Merkmale, Prozentangaben</caption><thead><tr><th>Merkmal</th><th>Gehört dazu</th><th>Erfüllt</th></tr></thead><tbody>${data.map(r=>`<tr>${r.map((v,i)=>`<${i?'td':'th scope="row"'}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div><p>Die Vorlage nennt weder Stichprobengröße noch Erhebungsmethode, Feldzeit oder genauen Fragewortlaut. Repräsentativität und Unsicherheit lassen sich anhand dieses Ausschnitts nicht abschließend prüfen.</p>`)}</section>`}
function renderChart(){let rows=[...data];if($('#sort').value==='gap')rows.sort((a,b)=>(b[1]-b[2])-(a[1]-a[2]));if(!$('#all').checked)rows=rows.slice(0,6);$('#social-chart').innerHTML=rows.map(([name,a,b])=>`<div class="chart-row"><span>${name}</span><div class="bars"><div class="bar" style="width:${a}%" aria-label="Gehört dazu: ${a} Prozent"><b>${a}</b></div><div class="bar second" style="width:${b}%" aria-label="Erfüllt: ${b} Prozent"><b>${b}</b></div></div></div>`).join('')}
const energy=`<div class="tablewrap"><table><caption>Erneuerbare Energien: in Deutschland erzeugter und ins öffentliche Netz eingespeister Strom</caption><thead><tr><th>Jahr</th><th>Anteil</th><th>Menge</th></tr></thead><tbody><tr><th scope="row">2023</th><td>56,0 %</td><td>250,7 Mrd. kWh</td></tr><tr><th scope="row">2024</th><td>59,4 %</td><td>256,4 Mrd. kWh</td></tr></tbody></table></div><small>Destatis, Pressemitteilung 091 vom 12.03.2025, damaliger vorläufiger Datenstand. Inländische Netzeinspeisung, nicht gesamter Stromverbrauch.</small>`;
const pages={
start:()=>`<span class="tag">WIRTSCHAFT & RECHT · KLASSE 11</span><div class="hero"><div><h1>Zahlen sehen.<br>Zusammenhänge<br>verstehen.</h1><p class="lead">Eine Statistik ist noch kein Argument. Lerne, aus Daten eine nachvollziehbare Aussage zu entwickeln und ihre Grenzen zu erkennen.</p><a class="primary" style="display:inline-block;padding:12px 24px;border-radius:8px;text-decoration:none" href="#beschreiben">Untersuchung starten →</a></div><div class="visual"><p>GLEICHE DATEN. ANDERE AUSSAGE?</p><div class="mini-bars" aria-label="Erneuerbaren-Anteil 2023: 56 Prozent; 2024: 59,4 Prozent"><i style="height:56%"><b>56,0 %</b></i><i style="height:59.4%"><b>59,4 %</b></i></div><p>2023 → 2024 · Erneuerbaren-Anteil</p><h2>+3,4 Prozentpunkte.<br>Oder +6,1 Prozent?</h2><p>Beides kann stimmen. Entscheidend ist, was du vergleichst.</p><small>Destatis · Netzeinspeisung · Datenakte 02</small></div></div><div class="steps"><div><span class="step-no">01</span><h2>Beschreiben</h2><p>Was wird gemessen? Kläre Thema, Einheit, Bezugsgruppe und Quelle.</p></div><div><span class="step-no">02</span><h2>Auswerten</h2><p>Welche Zusammenhänge zeigen sich? Berechne, vergleiche und belege.</p></div><div><span class="step-no">03</span><h2>Beurteilen</h2><p>Was darfst du folgern? Prüfe Darstellung, Interessen und Aussagegrenzen.</p></div></div><div class="callout"><strong>Dein Ziel: ein belastbares Urteil.</strong><p>Du untersuchst eine Umfrage, prüfst Energiedaten und experimentierst mit Achsen und Durchschnittswerten. Offene Denkaufträge verlangen Belege, Gegenargumente und eine Überarbeitung. Lösungen und Hilfen öffnest du selbst.</p></div>${finish('start','beschreiben')}`,
beschreiben:()=>heading('01','Erst die Daten. Dann die Deutung.','Bevor du eine Statistik interpretierst, musst du wissen, was ihre Zahlen überhaupt bedeuten.')+socialChart()+`<div class="callout"><strong>Beschreibung ≠ Erklärung</strong><p>„76 % nennen soziale Absicherung“ beschreibt einen Befund. „Weil die Menschen Angst haben“ ist eine mögliche Erklärung, die diese Statistik allein nicht belegt.</p></div>`+quiz('basis','Was bedeutet der Wert 59 bei „Absicherung“?', ['59 Menschen haben eine Versicherung.','59 % der Bevölkerung ab 16 Jahren halten diesen Aspekt in Deutschland für ausreichend erfüllt.','59 % aller Menschen weltweit sind sozial abgesichert.'],1,'Die zweite Reihe zeigt Einschätzungen der Bevölkerung ab 16 Jahren. Sie misst weder Versicherungsverträge noch objektive Versorgungsqualität.')+`<section class="panel"><span class="tag">ANGELEITETES BEISPIEL</span><h2>Von der Zahl zur vorsichtigen Aussage</h2><ol><li><strong>Ablesen:</strong> 76 % nennen soziale Absicherung als Merkmal; 59 % halten sie für ausreichend erfüllt.</li><li><strong>Vergleichen:</strong> 76 − 59 = 17 Prozentpunkte Abstand.</li><li><strong>Einordnen:</strong> Die Daten beschreiben Einschätzungen, keine objektiv gemessene Absicherung.</li><li><strong>Begrenzen:</strong> Ohne verknüpfte Einzelantworten folgt daraus nicht, dass genau 17 % unzufrieden sind.</li></ol><p><strong>Jetzt du:</strong> Übertrage diese vier Denkschritte auf ein anderes Merkmal, bevor du deinen Steckbrief schreibst.</p></section>`+task('beschreibung','Schreibe einen präzisen Statistik-Steckbrief.','Beschreibe Thema, Darstellungsform, Quelle, Jahr, Bezugsgruppe und Einheit. Trenne bekannte Angaben von fehlenden Informationen. Begründe, warum die fehlenden Angaben relevant sind.','Die Umfrage von 2021 stellt für 17 Merkmale zwei prozentuale Einschätzungen der Bevölkerung Deutschlands ab 16 Jahren gegenüber. Die Quelle wird als Allensbacher Archiv, IfD-Umfrage 12031 angegeben. Die Balken beschreiben Vorstellungen und wahrgenommene Erfüllung, keine objektiven Leistungskennzahlen. Ohne Stichprobengröße, Auswahlverfahren und Fragewortlaut bleibt offen, wie belastbar die Übertragung auf die Bevölkerung ist. Ein Jahr ist dargestellt; ein zeitlicher Trend lässt sich nicht ableiten.')+finish('beschreiben','auswerten'),
auswerten:()=>heading('02','Vergleichen heißt: genauer hinsehen.','Arbeite mit Abständen und Bezugsgrößen. Eine auffällige Zahl erklärt sich nicht von selbst.')+socialChart()+`<section class="panel"><h2>Prozent oder Prozentpunkte?</h2><p>Bei fairen Arbeitsbedingungen stehen 74 % Zustimmung und 24 % wahrgenommene Erfüllung gegenüber.</p><form id="calc"><label for="difference">Wie groß ist der Abstand in Prozentpunkten?</label><div class="toolbar"><input id="difference" type="number" step="any" required><button>Berechnung prüfen</button></div><div class="feedback" role="status" id="calc-feedback"></div></form>${details('Rechenhilfe','<p>Ein Abstand zwischen zwei Prozentangaben: 74 − 24. Eine relative Veränderung braucht dagegen einen ausdrücklich benannten Ausgangswert als Nenner.</p>')}</section>`+task('abstand','Welches Problem ist am größten?','Sortiere nach Abstand. Vergleiche faire Arbeitsbedingungen, gerechte Verteilung und Chancengerechtigkeit. Entwickle zwei unterschiedliche Kriterien für „größtes Problem“. Prüfe anschließend, ob die Statistik diese politische Wertung überhaupt rechtfertigt.','Der größte Abstand liegt bei fairen Arbeitsbedingungen mit 50 Prozentpunkten; gerechte Verteilung folgt mit 48, Chancengerechtigkeit mit 47. Nach niedrigster wahrgenommener Erfüllung wäre Verteilung (4 %) auffälliger als Arbeitsbedingungen (24 %). Nach Zustimmung stehen Arbeitsbedingungen (74 %) vor Chancengerechtigkeit (59 %) und Verteilung (52 %). Die Wahl des Kriteriums verändert die Rangfolge. Diese Abstände sind keine gemessenen objektiven Defizite und nicht automatisch der Anteil unzufriedener Einzelpersonen: Dafür braucht man verknüpfte Antworten derselben Befragten.')+quiz('freiheit','Bei unternehmerischer Freiheit stehen 36 % und 39 %. Welche Aussage ist zulässig?',['Die Umfrage ist wegen des Widerspruchs falsch.','Die Erfüllungswahrnehmung liegt 3 Prozentpunkte über der Nennung als Merkmal.','Die Freiheit hat seit dem Vorjahr um 3 % zugenommen.'],1,'Die Reihen erfassen verschiedene Einschätzungen. Sie müssen nicht gleich groß sein. Ohne Vorjahreswerte ist keine zeitliche Veränderung belegbar.')+finish('auswerten','beurteilen'),
beurteilen:()=>heading('03','Wie viel trägt deine Schlussfolgerung?','Prüfe, was die Statistik zeigt, was sie offenlässt und welche zusätzlichen Belege du brauchst.')+`<section class="panel dark"><span class="tag">BEHAUPTUNG AUF DEM PRÜFSTAND</span><h2>„Nur 4 % finden die Verteilung gerecht. Damit ist bewiesen: Die Soziale Marktwirtschaft ist gescheitert.“</h2><p>Ein Kommentar beruft sich auf die Umfrage von 2021. Untersuche den Weg von der Zahl zur politischen Schlussfolgerung.</p></section>`+task('kritik','Zerlege das Argument.','Formuliere die stärkste durch die Daten gestützte Aussage. Benenne mindestens zwei problematische Schlussfolgerungen. Entwickle eine faire Gegenposition und schlage zwei zusätzliche Untersuchungen vor.','4 % halten das Merkmal gerechte Verteilung in Deutschland für ausreichend erfüllt. Das deutet auf eine geringe wahrgenommene Erfüllung dieses Merkmals hin. Es beweist weder eine objektiv ungerechte Verteilung nach einem bestimmten Maßstab noch das Scheitern einer gesamten Wirtschaftsordnung. Eine Gegenposition kann auf andere Merkmale und unterschiedliche Gerechtigkeitsvorstellungen verweisen, ohne die geringe Zustimmung wegzuerklären. Nötig wären beispielsweise Verteilungsdaten nach Steuern und Transfers, Vergleiche über Zeit oder Länder sowie der genaue Fragewortlaut und Angaben zur Stichprobe.')+`<section class="panel"><h2>Quellenprüfung: Was würdest du nachfordern?</h2>${quiz('quelle','Eine freiwillige Online-Abstimmung unter 20.000 Lesern belegt die Meinung „der Deutschen“. Was ist der wichtigste Einwand?',['20.000 ist immer zu klein.','Selbstselektion kann die Stichprobe verzerren; Größe allein schafft keine Repräsentativität.','Online-Daten sind grundsätzlich unbrauchbar.'],1,'Entscheidend sind Auswahl und Teilnahme, nicht nur die Anzahl. Ein systematisch verzerrtes Auswahlverfahren wird durch mehr Antworten nicht automatisch repräsentativ.')}<p><strong>Weitere Prüffragen:</strong> Wer beauftragt und veröffentlicht? Sind Interessen erkennbar? Passen Überschrift und Messgröße zusammen? Fehlen Gruppen? Ist die Achse gleichmäßig? Sind gerundete Summen plausibel?</p></section>`+finish('beurteilen','labor'),
labor:()=>heading('04','Verändere den Blick auf die Zahlen.','In drei Experimenten überprüfst du, wie Darstellung, Kennzahl und Bezugsgröße ein Urteil beeinflussen.')+`<section class="panel"><span class="tag">EXPERIMENT A · ECHTE DATEN</span><h2>Ein kleiner Anstieg, dramatisch dargestellt.</h2>${energy}<label for="axis">Startwert der vertikalen Achse: <strong id="axis-label">0 %</strong></label><input id="axis" type="range" min="0" max="50" step="10" value="0"><div id="energy-chart"></div><p id="axis-comment" role="status"></p>${note('achse','Welche Darstellung würdest du veröffentlichen und warum?','Beschreibe den optischen Effekt, die unveränderten Zahlen und die Funktion eines Nullpunkts bei Balken.')}</section><section class="panel"><span class="tag">EXPERIMENT B · MODELLDATEN, KEINE ERHEBUNG</span><h2>Wie „typisch“ ist der Durchschnitt?</h2><p>Fünf fiktive monatliche Einkommen: 1.800 €, 2.000 €, 2.200 €, 2.400 € und ein veränderbares fünftes Einkommen.</p><label for="outlier">Fünftes Einkommen: <strong id="income-label"></strong></label><input id="outlier" type="range" min="2600" max="20000" step="100" value="2600"><div class="split"><div><span>Mittelwert</span><div class="number" id="mean"></div></div><div><span>Median</span><div class="number" id="median">2.200 €</div></div></div>${note('mittelwert','Welche Kennzahl beschreibt hier ein typisches Einkommen besser?','Beziehe dich auf zwei Reglerstellungen. Erkläre auch, welche Information der Median nicht liefert.')}${details('Auswertung','<p>Bei 2.600 € betragen Mittelwert und Median jeweils 2.200 €. Bei 20.000 € steigt der Mittelwert auf 5.680 €, während der Median bei 2.200 € bleibt. Der Median ist robust gegen den hohen Einzelwert. Er zeigt aber weder die Gesamtsumme noch die Streuung vollständig. Eine begründete Darstellung nennt daher beide Kennzahlen und ihre Funktion.</p>')}</section><section class="panel"><span class="tag">EXPERIMENT C · MODELLDATEN, KEINE ERHEBUNG</span><h2>Wo passieren mehr Unfälle?</h2><p>Stadt A: 120 Unfälle bei 100.000 Einwohnern. Stadt B: 80 Unfälle bei 40.000 Einwohnern. Fiktive Jahresdaten.</p><div class="toolbar"><button id="absolute" aria-pressed="true">Absolute Zahlen</button><button id="relative" aria-pressed="false">Je 100.000 Einwohner</button></div><div id="cities"></div>${note('vergleich','Reicht das für die Aussage „Stadt B ist gefährlicher“?','Vergleiche die Rangfolgen und diskutiere Einwohnerzahl, Verkehrsaufkommen, Pendler und Erhebungsmethode.')}${details('Auswertung','<p>Absolut liegt A mit 120 vor B mit 80. Je 100.000 Einwohner ergeben sich A: 120 und B: 200. Die Rangfolge kehrt sich um. Das individuelle Verkehrsrisiko folgt daraus nicht unmittelbar: Fahrleistung, Pendlerverkehr und Unfallschwere fehlen.</p>')}</section>`+finish('labor','transfer'),
transfer:()=>heading('05','Dein Urteil muss einen Einwand aushalten.','Wende die Methode auf einen neuen Zusammenhang an. Formuliere eine Aussage, die du auch nach kritischer Prüfung vertreten kannst.')+`<section class="panel"><span class="tag">DATENAKTE 02 · ENERGIE</span><h2>Mehr Anteil bedeutet nicht gleich viel mehr Strom.</h2>${energy}<p>Redaktion A: „Erneuerbarer Strom legt um 6,1 % zu.“<br>Redaktion B: „Erneuerbarer Strom legt um 2,3 % zu.“</p><p><strong>Dein Auftrag:</strong> Prüfe beide Schlagzeilen rechnerisch. Welche Bezugsgröße verwenden sie? Schreibe eine eigene präzisere Überschrift.</p>${note('energie','Deine Berechnungen und Überschrift')}${details('Hilfe 1 · Bezugsgröße finden','<p>Unterscheide den Anteil an der Einspeisung von der erzeugten Menge. Verwende jeweils (neuer Wert − alter Wert) ÷ alter Wert × 100.</p>')}${details('Hilfe 2 · Rechenansatz','<p>Anteil: (59,4 − 56,0) ÷ 56,0 × 100. Menge: (256,4 − 250,7) ÷ 250,7 × 100.</p>')}${details('Vergleichslösung','<p>Der Anteil steigt relativ um rund 6,1 %, die erzeugte Menge um rund 2,3 %. Absolut wächst der Anteil um 3,4 Prozentpunkte. A ist ohne den Zusatz „Anteil“ missverständlich. B beschreibt die Menge, sollte aber die inländische Netzeinspeisung nennen. Präzise: „Erneuerbare Netzeinspeisung 2024: Menge steigt um 2,3 %, Anteil auf 59,4 %.“</p>')}</section>`+task('urteil','Berate eine skeptische Redaktion.','Verfasse ein zusammenhängendes Urteil zu einer der beiden Datenakten. Beschreibe zuerst knapp die Grundlage, entwickle mindestens zwei belegte Aussagen und prüfe eine plausible Gegenposition. Benenne zwei Grenzen und eine konkrete weiterführende Untersuchung. Unterscheide ausdrücklich Befund, Erklärung und Wertung.','Beispiel Energie: Die Destatis-Daten zeigen für 2023 und 2024 einen Anstieg von Menge und Anteil erneuerbarer Netzeinspeisung. Die Menge wächst nur um etwa 2,3 %, der Anteil relativ um etwa 6,1 %. Der stärkere Anteilsanstieg hängt auch mit der sinkenden gesamten inländischen Einspeisung zusammen. Die Daten belegen deshalb keine gleich hohe Ausweitung der erneuerbaren Erzeugung und keine entsprechende Veränderung des gesamten Energieverbrauchs. Als Gegenposition bleibt richtig, dass der erneuerbare Anteil tatsächlich gestiegen ist. Für ein Urteil über die Energiewende sind zusätzlich Verbrauch, Importe, Emissionen, Kosten und ein längerer Zeitraum nötig.')+task('forschungsplan','Entwickle deine eigene Untersuchung.','Formuliere eine prüfbare Frage, die eine der Datenakten offenlässt. Lege fest, welche Daten du benötigst, wie du Gruppen fair vergleichst und welcher Befund deiner Vermutung widersprechen würde. Begründe eine methodische Grenze deines Plans.','Mögliche Untersuchung: Hängt die wahrgenommene Verteilungsgerechtigkeit mit der eigenen Einkommensposition zusammen? Dazu wären gemeinsam erhobene Angaben zur Einschätzung und zum bedarfsgewichteten Haushaltseinkommen nötig, mit einer nachvollziehbar ausgewählten Stichprobe. Alters- und Bildungsunterschiede sollten berücksichtigt werden. Ein fehlender oder entgegengesetzter Zusammenhang spräche gegen die Vermutung. Auch ein Zusammenhang bewiese noch keine Kausalität. Andere tragfähige Fragen und Untersuchungspläne sind möglich.')+`<section class="panel"><h2>Prüfe und überarbeite dein Urteil.</h2><p>Die offenen Texte werden nicht automatisch als richtig bewertet. Prüfe sie am Raster und begründe deine Selbsteinschätzung.</p>${['Ich benenne Quelle, Zeitraum, Einheit und Bezugsgruppe.','Ich belege mindestens zwei Aussagen mit passenden Zahlen.','Meine Rechnung und mein Vergleich verwenden dieselbe Bezugsgröße.','Ich trenne Beobachtung von Erklärung und Wertung.','Ich prüfe eine ernsthafte Gegenposition.','Ich benenne Grenzen und konkret benötigte Zusatzdaten.'].map((t,i)=>`<label class="check"><input type="checkbox" data-check="r${i}" ${state.checks['r'+i]?'checked':''}>${t}</label>`).join('')}${note('revision','Was hast du nach der Prüfung verbessert?','Nenne eine ursprüngliche Aussage und deine begründete Überarbeitung.')}<button id="print">Diese Seite drucken / als PDF speichern</button></section>`+finish('transfer','quellen'),
quellen:()=>heading('NACHSCHLAGEN','Begriffe, Methode und Quellen.','Eine gute Auswertung macht ihren Weg von der Quelle zur Schlussfolgerung sichtbar.')+`<section class="panel"><h2>Werkzeugkasten</h2><dl><dt><strong>Absoluter Wert</strong></dt><dd>Eine Anzahl oder Menge, etwa 120 Unfälle.</dd><dt><strong>Relativer Wert</strong></dt><dd>Eine Größe bezogen auf eine andere, etwa 20 % oder 200 Unfälle je 100.000 Einwohner.</dd><dt><strong>Prozentpunkte</strong></dt><dd>Differenz zweier Prozentangaben: 59,4 % − 56,0 % = 3,4 Prozentpunkte.</dd><dt><strong>Relative Veränderung</strong></dt><dd>(Neuer Wert − alter Wert) ÷ alter Wert × 100. Bei Ausgangswert 0 ist diese Rechnung nicht definiert.</dd><dt><strong>Mittelwert und Median</strong></dt><dd>Mittelwert: Summe geteilt durch Anzahl. Median: mittlerer Wert der sortierten Daten; bei gerader Anzahl der Mittelwert der zwei mittleren Werte.</dd><dt><strong>Korrelation und Kausalität</strong></dt><dd>Ein gemeinsames Auftreten ist noch kein Nachweis einer Ursache. Drittvariablen oder die umgekehrte Wirkungsrichtung können eine Rolle spielen.</dd><dt><strong>Bereinigung</strong></dt><dd>Saisonbereinigt: wiederkehrende jahreszeitliche Effekte werden berücksichtigt. Kalenderbereinigt: Unterschiede bei Arbeitstagen. Real: Preisänderungen werden herausgerechnet. Vergleiche nur methodisch passende Reihen.</dd><dt><strong>Stichprobe</strong></dt><dd>Untersuchter Teil einer Grundgesamtheit. Aussagekraft hängt unter anderem von Auswahl, Größe, Teilnahme und Messmethode ab.</dd></dl></section><section class="panel"><h2>Quellen und Transparenz</h2><p><strong>Datenakte 01:</strong> Vom Nutzer bereitgestellte Buchseiten „Statistiken auswerten und deren Aussagekraft beurteilen“. Quellenangabe der Abbildung: Allensbacher Archiv, IfD-Umfrage 12031, 2021; Bevölkerung ab 16 Jahren. Die Zahlen wurden aus der Abbildung übertragen. Die Originalerhebung wurde nicht unabhängig geprüft. Aufgaben und Darstellung sind neu erstellt; die Buchseiten werden nicht veröffentlicht.</p><p><strong>Datenakte 02:</strong> <a href="https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/03/PD25_091_43312.html">Statistisches Bundesamt: Stromerzeugung 2024, Pressemitteilung 091 vom 12. März 2025</a>. Verwendet wird dieser dokumentierte Datenstand, keine laufend aktualisierte Zeitreihe.</p><p><strong>Experimente B und C:</strong> eigens konstruierte, ausdrücklich fiktive Modelldaten, ausschließlich zum Üben. Keine Aussagen über reale Einkommen oder Städte.</p><p><strong>Methode:</strong> Beschreiben → Auswerten → Aussagekraft beurteilen, angelehnt an die bereitgestellten Methodenseiten. Die Lernaufgaben ergänzen Perspektivwechsel, Transfer, Gegenargumente und Reflexion.</p><p><strong>Speicherung:</strong> Kein Konto und keine Übermittlung deiner Antworten. Texte und Fortschritt werden nur im Browser gespeichert. Auf gemeinsam genutzten Geräten nach dem Export zurücksetzen.</p></section>`};
function progress(){updateCompletion();const n=Object.values(state.done).filter(Boolean).length;$('#progress-text').textContent=n===5?'✓ Lernstrecke erledigt · 5 von 5 Stationen':`${n} von 5 Aufgabenstationen erledigt`;$('#progress').value=n;
 document.querySelectorAll('[data-completion]').forEach(el=>{const id=el.dataset.completion;const missing=stationRules[id].filter(r=>!requirementMet(r));el.innerHTML=missing.length?`<strong>Noch offen (${missing.length})</strong><ul>${missing.map(r=>`<li>${r[2]}</li>`).join('')}</ul><small>Der Abschluss erfolgt automatisch. Er bestätigt den Bearbeitungsumfang, keine fachliche Bewertung.</small>`:'<strong>✓ Station erledigt</strong><small>Alle Aufgaben ausreichend bearbeitet. Vergleiche deine Argumentation weiterhin mit den Kriterien und Musterlösungen.</small>'});
 document.querySelectorAll('#nav a').forEach(a=>{const id=a.hash.slice(1);let badge=a.querySelector('.done-badge');if(state.done[id]&&!badge){badge=document.createElement('b');badge.className='done-badge';badge.textContent='✓';badge.setAttribute('aria-label','erledigt');a.append(badge)}else if(!state.done[id]&&badge)badge.remove()});
}
function energyChart(){const base=Number($('#axis').value);$('#axis-label').textContent=base+' %';$('#energy-chart').innerHTML=`<svg viewBox="0 0 500 230" role="img" aria-label="Balkendiagramm: 2023 56 Prozent, 2024 59,4 Prozent. Achse beginnt bei ${base} Prozent." style="width:100%;max-height:280px">${[base,(base+100)/2,100].map(v=>{let y=190-(v-base)/(100-base)*160;return `<line x1="65" y1="${y}" x2="470" y2="${y}" stroke="#b4bba9"/><text x="5" y="${y+5}" font-size="14" fill="#394633">${v} %</text>`}).join('')}${[56,59.4].map((v,i)=>{let h=(v-base)/(100-base)*160;return `<rect x="${120+i*180}" y="${190-h}" width="90" height="${h}" fill="#315641"/><text x="${165+i*180}" y="${180-h}" text-anchor="middle" font-size="16" fill="#253326">${String(v).replace('.',',')} %</text><text x="${165+i*180}" y="218" text-anchor="middle" font-size="16" fill="#253326">${2023+i}</text>`}).join('')}</svg>`;$('#axis-comment').textContent=base?'Achtung: verkürzte Achse. Der sichtbare Höhenunterschied wirkt relativ größer; die Werte bleiben unverändert.':'Die Balken beginnen bei null. Ihre Höhen bilden die Anteile proportional ab.'}
function income(){const n=Number($('#outlier').value);$('#income-label').textContent=n.toLocaleString('de-DE')+' €';$('#mean').textContent=((8400+n)/5).toLocaleString('de-DE')+' €'}
function cities(relative=false){$('#absolute').setAttribute('aria-pressed',!relative);$('#relative').setAttribute('aria-pressed',relative);$('#cities').innerHTML=[['Stadt A',120],['Stadt B',relative?200:80]].map(([c,v])=>`<div class="chart-row"><strong>${c}</strong><div class="bar" style="width:${v/2}%"><b>${v}</b></div></div>`).join('')+`<small>${relative?'Unfälle je 100.000 Einwohner':'Anzahl der Unfälle'} · Skala 0–200</small>`}
function gateSolutions(){document.querySelectorAll('[data-note]').forEach(t=>{const result=assessAnswer(t.dataset.note,t.value);$('#'+t.id+'-status').textContent=result.message;});document.querySelectorAll('details').forEach(d=>{const summary=d.querySelector('summary');if(!/Vergleichslösung|^Auswertung/.test(summary.textContent))return;const section=d.closest('section');const inputs=[...section.querySelectorAll('textarea')];const ready=inputs.length>0&&inputs.every(t=>assessAnswer(t.dataset.note,t.value).ready);d.dataset.solution='true';summary.setAttribute('aria-disabled',String(!ready));if(!ready)d.open=false;let hint=d.querySelector('[data-lock]');if(!hint){hint=document.createElement('span');hint.dataset.lock='true';summary.append(hint)}hint.textContent=ready?'':' · erst ausreichend ausführlich antworten';});}
function render(){const route=location.hash.slice(1);const id=pages[route]?route:'start';$('#nav').innerHTML=routes.map(([r,n],i)=>`<a href="#${r}" ${id===r?'aria-current="page"':''}><span>${String(i).padStart(2,'0')}</span>${n}</a>`).join('');$('#content').innerHTML=pages[id]();document.title=`${routes.find(r=>r[0]===id)[1]} · Statistiklabor Klasse 11`;if($('#social-chart')){renderChart();$('#sort').onchange=renderChart;$('#all').onchange=renderChart}if($('#axis')){$('#axis').oninput=()=>{energyChart();state.activity.axis=true;save()};energyChart();$('#outlier').oninput=()=>{income();state.activity.outlier=true;save()};income();$('#absolute').onclick=()=>cities();$('#relative').onclick=()=>{cities(true);state.activity.cities=true;save()};cities()}if($('#print'))$('#print').onclick=()=>window.print();document.querySelectorAll('.quiz').forEach(f=>{const prior=state.quiz[f.dataset.id];if(prior){const input=f.querySelector(`input[value="${prior.value}"]`);if(input)input.checked=true;if(prior.passed)f.querySelector('.feedback').textContent='Richtig beantwortet. '+f.querySelector('.feedback').dataset.explain}});if($('#difference')){$('#difference').value=state.calc.value||'';if(state.calc.passed)$('#calc-feedback').textContent='Richtig: 50 Prozentpunkte.'}gateSolutions();progress()}
document.addEventListener('input',e=>{if(e.target.id==='difference'){state.calc={value:e.target.value,passed:false};save()}if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;save();gateSolutions()}});
document.addEventListener('change',e=>{if(e.target.closest('.quiz')){state.quiz[e.target.name]={value:e.target.value,passed:false};e.target.closest('.quiz').querySelector('.feedback').textContent='Auswahl geändert. Prüfe deine Antwort erneut.';save()}if(e.target.dataset.check){state.checks[e.target.dataset.check]=e.target.checked;save()}});
document.addEventListener('click',e=>{const summary=e.target.closest('summary');if(summary?.getAttribute('aria-disabled')==='true')e.preventDefault()});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.classList.contains('quiz')){const selected=new FormData(f).get(f.dataset.id);state.quiz[f.dataset.id]={value:selected,passed:selected===f.dataset.correct};save();const out=f.querySelector('.feedback');out.textContent=(selected===f.dataset.correct?'Richtig. ':'Überdenke deine Antwort. ')+out.dataset.explain}if(f.id==='calc'){const v=Number($('#difference').value);state.calc={value:$('#difference').value,passed:v===50};save();$('#calc-feedback').textContent=v===50?'Richtig: 74 − 24 = 50 Prozentpunkte. Daraus folgt nicht automatisch, dass 50 % derselben Personen unzufrieden sind.':'Noch nicht. Subtrahiere 24 von 74; der Abstand wird in Prozentpunkten angegeben.'}});
$('#reset').onclick=()=>{if(confirm('Alle Texte und den Fortschritt in diesem Browser löschen? Lade sie bei Bedarf zuerst herunter.')){state={notes:{},checks:{},done:{},quiz:{},activity:{},calc:{}};save();render()}};
$('#export').onclick=()=>{const text=['STATISTIKLABOR · KLASSE 11','Arbeitsstand · '+new Date().toLocaleDateString('de-DE'),...Object.entries(state.notes).map(([k,v])=>`\n${k.toUpperCase()}\n${v}`),'\nAUTOMATISCH ABGESCHLOSSENE STATIONEN',...Object.entries(state.done).filter(([,v])=>v).map(([k])=>k),'\nKRITERIENRASTER',...Object.entries(state.checks).map(([k,v])=>`${k}: ${v?'geprüft':'offen'}`)].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='statistiklabor-arbeitsstand.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.addEventListener('hashchange',()=>{render();$('#content').focus();window.scrollTo(0,0)});render();
